<script setup lang="ts">
import { computed, ref } from 'vue';import { Head, Link, usePage } from '@inertiajs/vue3';import { writeCart, readCart, type CartItem } from '@/lib/cart';
type P={id:number;slug:string;name:string;category:string;categorySlug:string;brand:string;price:number;oldPrice?:number|null;image?:string|null;badge?:string|null;rating:number;sold:number;stock:number;productType?:string|null;productLine?:string|null};type C={id:number;name:string;slug:string;icon:string|null;count:number};type F={brands:string[];types:string[];lines:string[]};
const props=defineProps<{category?:string;search?:string;products:P[];categories:C[];filters:F}>();const page=usePage();const userId=computed(()=>((page.props as any).auth?.user?.id??null) as number|null);const q=ref(props.search??'');const brand=ref('');const type=ref('');const line=ref('');const min=ref('');const max=ref('');const sort=ref('featured');const current=ref(1);const perPage=12;const category=ref(props.category||'all');
const filtered=computed(()=>{let a=props.products;if(category.value!=='all')a=a.filter(x=>x.categorySlug===category.value);const s=q.value.trim().toLowerCase();if(s)a=a.filter(x=>`${x.name} ${x.brand} ${x.category} ${x.productLine??''} ${x.productType??''} ${x.sku??''}`.toLowerCase().includes(s));if(brand.value)a=a.filter(x=>x.brand===brand.value);if(type.value)a=a.filter(x=>x.productType===type.value);if(line.value)a=a.filter(x=>x.productLine===line.value);if(min.value)a=a.filter(x=>x.price>=Number(min.value));if(max.value)a=a.filter(x=>x.price<=Number(max.value));if(sort.value==='low')a=[...a].sort((x,y)=>x.price-y.price);if(sort.value==='high')a=[...a].sort((x,y)=>y.price-x.price);if(sort.value==='rating')a=[...a].sort((x,y)=>y.rating-x.rating);return a});const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/perPage)));const shown=computed(()=>filtered.value.slice((current.value-1)*perPage,current.value*perPage));const fmt=(n:number)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n);const count=(key:string,value:string)=>props.products.filter(x=>String((x as any)[key]??'')===value).length;function reset(){q.value='';brand.value='';type.value='';line.value='';min.value='';max.value='';current.value=1}function add(p:P){const c=readCart(userId.value);const x=c.find(i=>i.id===p.id);if(x)x.quantity=Math.min(p.stock,x.quantity+1);else c.push({id:p.id,name:p.name,price:p.price,image:p.image??'',quantity:1} as CartItem);writeCart(userId.value,c)}
</script>
<template><Head title="Khám phá sản phẩm"/><main class="catalog"><div class="crumb"><Link href="/">Trang chủ</Link><i class="bi bi-chevron-right"/>Khám phá sản phẩm</div><header class="hero"><div><span>TECHSTORE · CỬA HÀNG CÔNG NGHỆ</span><h1>Khám phá sản phẩm</h1><p>Tìm theo thương hiệu, loại sản phẩm, dòng/series, khoảng giá hoặc mã sản phẩm.</p></div><strong>{{filtered.length}} sản phẩm</strong></header><div class="layout"><aside class="filters"><div class="filter-head"><h3>Bộ lọc chi tiết</h3><button @click="reset">Xóa lọc</button></div><label>Tìm kiếm / mã sản phẩm</label><div class="search"><i class="bi bi-search"/><input v-model="q" placeholder="Tên, SKU, mã sản phẩm..."/></div><label>Thương hiệu</label><select v-model="brand"><option value="">Tất cả thương hiệu</option><option v-for="b in filters.brands" :key="b" :value="b">{{b}} · {{count('brand',b)}} dòng</option></select><label>Loại sản phẩm</label><select v-model="type"><option value="">Tất cả loại</option><option v-for="t in filters.types" :key="t" :value="t">{{t}} · {{count('productType',t)}} dòng</option></select><label>Dòng sản phẩm / Series</label><select v-model="line"><option value="">Tất cả dòng</option><option v-for="l in filters.lines" :key="l" :value="l">{{l}} · {{count('productLine',l)}} dòng</option></select><label>Khoảng giá</label><div class="price"><input v-model="min" inputmode="numeric" placeholder="Từ"/><input v-model="max" inputmode="numeric" placeholder="Đến"/></div><div class="filter-note"><i class="bi bi-upc-scan"/><span>Tìm bằng SKU/mã sản phẩm phù hợp cho khách hàng và bộ phận bán hàng.</span></div></aside><section class="results"><div class="toolbar"><span><strong>{{filtered.length}}</strong> kết quả</span><select v-model="sort"><option value="featured">Nổi bật</option><option value="rating">Đánh giá cao</option><option value="low">Giá thấp → cao</option><option value="high">Giá cao → thấp</option></select></div><div v-if="shown.length" class="grid"><article v-for="p in shown" :key="p.id" class="card"><div class="image"><img :src="p.image||''" :alt="p.name"/><span v-if="p.badge">{{p.badge}}</span></div><div class="body"><small>{{p.brand}} · {{p.productLine||p.productType||p.category}}</small><h2>{{p.name}}</h2><div class="meta"><span><i class="bi bi-star-fill"/> {{p.rating}}</span><span>Đã bán {{p.sold}}</span></div><strong class="price">{{fmt(p.price)}}</strong><del v-if="p.oldPrice">{{fmt(p.oldPrice)}}</del><div class="actions"><Link :href="`/products/${p.slug}`">Xem chi tiết <i class="bi bi-arrow-right"/></Link><button @click="add(p)" :disabled="p.stock<1"><i class="bi bi-cart-plus"/></button></div></div></article></div><div v-else class="empty"><i class="bi bi-search"/><h3>Không tìm thấy sản phẩm</h3><button @click="reset">Xóa bộ lọc</button></div><nav v-if="pages>1" class="pagination"><button :disabled="current===1" @click="current--">‹</button><button v-for="n in pages" :key="n" :class="{active:current===n}" @click="current=n">{{n}}</button><button :disabled="current===pages" @click="current++">›</button></nav></section></div></main></template>
<style scoped>.catalog{min-height:100vh;padding:24px 20px 65px;background:#f7f9fc}.crumb{display:flex;gap:8px;align-items:center;margin-bottom:18px;color:#98a2b3;font-size:.68rem}.crumb a{color:#667085}.hero{display:flex;justify-content:space-between;gap:15px;align-items:flex-start;padding:22px;margin-bottom:18px;border:1px solid #e4e7ec;border-radius:18px;background:#fff}.hero span,.head span{color:#2563eb;font-size:.58rem;font-weight:900;letter-spacing:.13em}.hero h1{margin:4px 0;font-size:1.7rem;font-weight:900}.hero p{margin:0;color:#667085;font-size:.7rem}.hero>strong{padding:8px 11px;border-radius:9px;color:#2563eb;background:#eff6ff;font-size:.65rem}.layout{display:grid;grid-template-columns:260px 1fr;gap:18px}.filters{position:sticky;top:15px;align-self:start;padding:16px;border:1px solid #e4e7ec;border-radius:16px;background:#fff}.filter-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:13px}.filter-head h3{margin:0;font-size:.9rem}.filter-head button{border:0;background:none;color:#2563eb;font-size:.6rem;font-weight:800}.filters label{display:block;margin:12px 0 5px;color:#667085;font-size:.6rem;font-weight:850}.search,.filters select,.price input{width:100%;border:1px solid #dfe5ee;border-radius:9px;background:#fff}.search{display:flex;align-items:center;padding:0 9px}.search i{color:#98a2b3}.search input,.filters select{height:38px;border:0;outline:0;font-size:.63rem}.search input{width:100%;padding:0 6px}.price{display:grid;grid-template-columns:1fr 1fr;gap:6px}.price input{height:38px;padding:0 8px;outline:0;font-size:.62rem}.filter-note{display:flex;gap:7px;margin-top:14px;padding:9px;border-radius:9px;color:#667085;background:#f8fafc;font-size:.58rem;line-height:1.45}.filter-note i{color:#2563eb}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;color:#667085;font-size:.68rem}.toolbar strong{color:#101828}.toolbar select{padding:8px;border:1px solid #dfe5ee;border-radius:9px;background:#fff;font-size:.63rem}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.card{overflow:hidden;border:1px solid #e4e7ec;border-radius:16px;background:#fff;box-shadow:0 7px 23px rgba(16,24,40,.04)}.image{position:relative;aspect-ratio:1.05;background:#f5f7fa}.image img{width:100%;height:100%;object-fit:cover}.image span{position:absolute;top:9px;left:9px;padding:5px 7px;border-radius:7px;color:#fff;background:#101828;font-size:.57rem;font-weight:800}.body{padding:12px}.body>small{color:#98a2b3;font-size:.56rem}.body h2{height:42px;margin:5px 0;font-size:.75rem;line-height:1.4}.meta{display:flex;justify-content:space-between;color:#98a2b3;font-size:.57rem}.meta i{color:#f59e0b}.body>.price{display:inline-block;margin-top:7px;color:#dc2626;font-size:.86rem}.body del{margin-left:5px;color:#98a2b3;font-size:.57rem}.actions{display:grid;grid-template-columns:1fr 38px;gap:6px;margin-top:10px}.actions a,.actions button{height:35px;display:grid;place-items:center;border:1px solid #bfdbfe;border-radius:8px;background:#fff;color:#2563eb;text-decoration:none;font-size:.6rem;font-weight:800}.actions button{background:#2563eb;color:#fff}.actions button:disabled{opacity:.45}.empty{padding:60px;text-align:center;border:1px dashed #d0d5dd;border-radius:15px;color:#98a2b3}.empty i{font-size:28px}.empty button{border:0;color:#2563eb;background:none;font-size:.65rem;font-weight:800}.pagination{display:flex;justify-content:center;gap:5px;margin-top:24px}.pagination button{min-width:34px;height:34px;border:1px solid #dfe5ee;border-radius:8px;background:#fff;font-size:.65rem}.pagination button.active{border-color:#2563eb;color:#fff;background:#2563eb}@media(max-width:1050px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:850px){.layout{grid-template-columns:1fr}.filters{position:static}.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:550px){.catalog{padding:15px 10px 45px}.hero>strong{display:none}.grid{grid-template-columns:1fr}.toolbar{align-items:flex-start;flex-direction:column;gap:8px}}
</style>
